package com.pulseloop.ui.theme

import androidx.compose.ui.graphics.Color

/**
 * The app's design tokens. Chrome follows the GMind brand (the dark values of GMind's
 * `ui-kit` UiTokens): page #121214, surface #1C1B1F, ink #F2F2F2, muted #A8A7AD, hairline
 * #2C2B30, and mint #43F3B7 as the one accent, with ink-green #033423 for text on it. The
 * metric, zone and stage colours are tuned to sit beside the mint rather than compete with
 * it. [MetricColors] and ZonePalette alias the zone colours below.
 *
 * Every value comes from [GTokens], generated by the shared design system
 * (github.com/gabrielbr/Gabriel-Deisgn-System, layer `pulseloop`). Change a colour there, then copy
 * the new GTokens.kt in; never write a Color(0x…) literal here. Screens keep reading PulseColors,
 * so FairyMode's getters keep working.
 */
object PulseColors {
    /** GMind mint. The brand colours below are getters so [FairyMode] can turn them pink. */
    private val MINT = GTokens.Colors.mint
    val background = GTokens.Colors.page
    val secondaryBackground = GTokens.Colors.pageRaised
    val card = GTokens.Colors.surface
    val cardSoft = GTokens.Colors.surfaceSoft
    val elevated = GTokens.Colors.surfaceElevated
    val textPrimary = GTokens.Colors.ink
    val textSecondary = GTokens.Colors.muted
    /** Tertiary text. #8E8D94 so it still reads at 4.5:1 on [card] and [cardSoft] (#7C7B82 was 4.1 / 3.7). */
    val textMuted = GTokens.Colors.muted2
    /** GMind mint: the primary action, the selected state, the screen frame. */
    val accent: Color get() = if (FairyMode.on) FairyMode.Palette.accent else MINT
    val accentSoft: Color get() = if (FairyMode.on) FairyMode.Palette.accentSoft else GTokens.Colors.mintSoft   // accent @ 18%
    /** Text and icons on a mint fill (GMind ON_MINT, 9:1 on mint). Never white on mint. */
    val onAccent: Color get() = if (FairyMode.on) FairyMode.Palette.onAccent else GTokens.Colors.onMint
    /**
     * "Good / in range / done". Its own green, not the mint: mint is the brand and the thing
     * to tap, and when it also meant success, connected and REM it stopped saying "act here".
     */
    val success = GTokens.Colors.success
    val warning = GTokens.Colors.warning
    val danger = GTokens.Colors.coral     // GMind coral (dark)
    val info = GTokens.Colors.info

    // Per-metric accents
    val steps = GTokens.Colors.metricSteps       // leaf green, distinct from the mint accent
    val heartRate = GTokens.Colors.metricHeartRate   // coral
    val spo2 = GTokens.Colors.metricSpo2
    val sleep = GTokens.Colors.metricSleep
    val calories = GTokens.Colors.metricCalories
    val distance = GTokens.Colors.metricDistance
    val battery = GTokens.Colors.metricBattery
    val stress = GTokens.Colors.metricStress
    val hrv = GTokens.Colors.metricHrv
    val temperature = GTokens.Colors.metricTemperature
    val bloodPressure = GTokens.Colors.metricBloodPressure
    val bloodSugar = GTokens.Colors.metricBloodSugar
    val fatigue = GTokens.Colors.metricFatigue
    val drinks = GTokens.Colors.metricDrinks     // wine rose
    val readiness: Color get() = accent   // the headline score wears the brand colour

    // Vitals reference-zone colors (AppTheme.swift zone*) — aliased by
    // ZonePalette (fine iOS-parity palette) and [MetricColors] (coarse semantic palette)
    val zoneBlue = GTokens.Colors.zoneLow
    /** The in-range zone. Named for its old mint; it is the [success] green now. */
    val zoneMint = GTokens.Colors.zoneGood
    val zoneCyan = GTokens.Colors.zoneNormal
    val zoneAmber = GTokens.Colors.zoneBorderline
    val zoneSoftAmber = GTokens.Colors.zoneBorderlineSoft
    val zoneOrange = GTokens.Colors.zoneElevated
    val zoneRed = GTokens.Colors.zoneHigh
    val zoneCritical = GTokens.Colors.zoneCritical

    // Sleep stage colors (DesignSystem/Charts.swift SleepStageColors)
    /** 3.3:1 on [card]: deep is the stage people look for, and #4B3BD6 was 2.4:1. */
    val stageDeep = GTokens.Colors.stageDeep
    val stageLight = GTokens.Colors.stageLight
    /** Cyan rather than the brand mint, so REM doesn't read as "tap here" (see [success]). */
    val stageRem: Color get() = if (FairyMode.on) FairyMode.Palette.rem else GTokens.Colors.stageRem
    val stageAwake = GTokens.Colors.stageAwake

    val borderSubtle = GTokens.Colors.line  // GMind hairline (LINE, dark)
    val borderStrong = GTokens.Colors.lineStrong

    /** The GMind frame: a 4dp mint border round every screen. */
    val frame: Color get() = accent
}
